def tier_lynx(url: str) -> tuple[str, str] | None:
    lynx = shutil.which("lynx")
    if not lynx:
        return None
    try:
        proc = subprocess.run(
            [lynx, "-dump", url],
            capture_output=True,
            text=True,
            timeout=CURL_TIMEOUT + 10,
        )
        text = clean_text(proc.stdout[:8000] if proc.stdout else "")
        if word_count(text) >= MIN_WORDS:
            return "lynx", text
    except (subprocess.SubprocessError, OSError):
        pass
    return None


def tier_webfetch(url: str) -> tuple[str, str] | None:
    try:
        import requests
        from bs4 import BeautifulSoup
        from markdownify import markdownify as md
    except ImportError:
        return None
    try:
        resp = requests.get(url, headers={"User-Agent": UA}, timeout=CURL_TIMEOUT)
        resp.raise_for_status()
        soup = BeautifulSoup(resp.text, "lxml")
        for tag in soup(["script", "style", "nav", "footer", "header"]):
            tag.decompose()
        article = soup.find("article") or soup.find("main") or soup.body
        if not article:
            return None
        text = clean_text(md(str(article), heading_style="ATX"))
        if word_count(text) >= MIN_WORDS:
            return "webfetch_markdownify", text
    except Exception:
        pass
    return None


def extract(url: str) -> dict:
    url = (url or "").strip()
    if not url:
        return {"ok": False, "error": "empty_url", "tier": None, "content": "", "words": 0}

    tiers = [
        tier_trafilatura_url,
        tier_curl_trafilatura,
        tier_bs4,
        tier_lynx,
        tier_webfetch,
    ]
    for fn in tiers:
        try:
            result = fn(url)
        except Exception:
            result = None
        if result:
            tier, content = result
            return {
                "ok": True,
                "url": url,
                "tier": tier,
                "content": content,
                "words": word_count(content),
            }
    return {"ok": False, "error": "all_tiers_failed", "tier": None, "content": "", "words": 0}


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("url")
    parser.add_argument("--json", action="store_true", help="Output JSON instead of raw text")
    args = parser.parse_args()

    result = extract(args.url)
    if result["ok"]:
        print(f"EXTRACT_OK: tier={result['tier']} words={result['words']}", file=sys.stderr)
        if args.json:
            print(json.dumps(result, ensure_ascii=False))
        else:
            print(result["content"])
        return 0
    print(f"EXTRACT_FAILED: {result.get('error', 'unknown')}", file=sys.stderr)
    if args.json:
        print(json.dumps(result, ensure_ascii=False))
    return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Web Reader Pro - Advanced Web Content Extraction for OpenClaw

A multi-tier web content extraction system with:
- Three-tier fallback strategy (Jina → Scrapling → WebFetch)
- Jina quota monitoring and alerting
- Smart cache layer
- Quality scoring and auto-escalation
- Domain-level routing learning
- Exponential backoff retry
"""

import os
import re
import time
import json
import hashlib
import logging
import datetime
from pathlib import Path
from typing import Dict, Optional, Tuple, Any
from dataclasses import dataclass, asdict
from enum import Enum
from urllib.parse import urlparse

import requests
from tenacity import (
    retry,
    stop_after_attempt,
    wait_exponential,
    retry_if_exception_type,
)

# Optional imports with fallbacks
try:
    from bs4 import BeautifulSoup
    BS4_AVAILABLE = True
except ImportError:
    BS4_AVAILABLE = False

try:
    import markdownify
    MARKDOWNIFY_AVAILABLE = True
except ImportError:
    MARKDOWNIFY_AVAILABLE = False

try:
    import diskcache
    DISKCACHE_AVAILABLE = True
except ImportError:
    DISKCACHE_AVAILABLE = False

try:
    from selectolax.parser import HTMLParser
    SELECTOLAX_AVAILABLE = True
except ImportError:
    SELECTOLAX_AVAILABLE = False

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger("web-reader-pro")


class ExtractionTier(str, Enum):
    """Extraction tier enumeration"""
    JINA = "jina"
    SCRAPLING = "scrapling"
    WEBFETCH = "webfetch"

    @classmethod
    def get_order(cls) -> list:
        return [cls.JINA, cls.SCRAPLING, cls.WEBFETCH]

    @classmethod
    def get_next(cls, tier: 'ExtractionTier') -> Optional['ExtractionTier']:
        order = cls.get_order()
        try:
            idx = order.index(tier)
            return order[idx + 1] if idx < len(order) - 1 else None
        except ValueError:
            return None


@dataclass
class ExtractionResult:
    """Result container for extracted content"""
    title: str
    content: str
    url: str
    tier_used: str
    quality_score: int
    cached: bool
    domain_learned_tier: Optional[str] = None
    extracted_at: str = None

    def __post_init__(self):
        if self.extracted_at is None:
            self.extracted_at = datetime.datetime.utcnow().isoformat() + "Z"

    def to_dict(self) -> Dict:
        return asdict(self)


@dataclass
class JinaQuotaStatus:
    """Jina API quota status"""
    call_count: int
    limit: int
    percentage: float
    warning_issued: bool
    exhausted: bool

    def to_dict(self) -> Dict:
        return asdict(self)


class JinaQuotaMonitor:
    """
    Jina API quota monitoring system.
    Tracks API call count and warns when approaching limits.
    """

    DEFAULT_QUOTA_LIMIT = 100000
    WARNING_THRESHOLD = 0.80  # Warn at 80% usage
    CRITICAL_THRESHOLD = 0.95  # Critical at 95% usage

    def __init__(self, quota_limit: int = None, storage_path: str = None):
        self.limit = quota_limit or int(os.environ.get(
            'WEB_READER_JINA_QUOTA', self.DEFAULT_QUOTA_LIMIT
        ))
        self.storage_path = self._get_storage_path(storage_path)
        self._ensure_storage()

    def _get_storage_path(self, storage_path: str = None) -> Path:
        if storage_path:
            return Path(storage_path)
        cache_dir = Path(os.environ.get(
            'WEB_READER_CACHE_DIR',
            Path.home() / '.openclaw' / 'cache' / 'web-reader-pro'
        ))
        return cache_dir / 'jina_quota.json'

    def _ensure_storage(self):
        self.storage_path.parent.mkdir(parents=True, exist_ok=True)
        if not self.storage_path.exists():
            self._save_state({'count': 0, 'last_reset': time.time()})

